window.Regntid.register('history',function(window,document){const $=id=>document.getElementById(id),M=window.RainModel;let model=M.createModel(window.RAIN_DATA);const anomaly=x=>(x>=0?'+':'−')+Math.abs(x).toFixed(0)+' %';function renderHistory(){const seq=model.history(),W=1120,H=230,p={l:45,r:12,t:16,b:35},cw=W-p.l-p.r,ch=H-p.t-p.b,max=80,y=v=>p.t+(max-v)/(max*2)*ch;let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Rullerende 12 måneders nedbøravvik i valgt måleserie">`;for(const v of [-50,0,50])svg+=`<line x1="${p.l}" x2="${W-p.r}" y1="${y(v)}" y2="${y(v)}" stroke="#d9e4e6"/><text x="${p.l-7}" y="${y(v)+4}" text-anchor="end" fill="#71868e" font-size="11">${v>0?'+':''}${v}%</text>`;seq.forEach((s,i)=>{const x=p.l+i/seq.length*cw;svg+=`<rect x="${x}" y="${Math.min(y(s.value),y(0))}" width="${cw/seq.length+.15}" height="${Math.abs(y(s.value)-y(0))}" fill="${s.value>=0?'#188e84':'#d7a15b'}"><title>${s.label}: ${anomaly(s.value)}</title></rect>`;const d=M.date(s.index);if(d.month===1&&d.year%20===0)svg+=`<text x="${x}" y="${H-9}" text-anchor="middle" font-size="12" fill="#71868e">${d.year}</text>`});$('historyChart').innerHTML=svg+'</svg>'}
renderHistory();window.addEventListener('frost-updated',()=>{model=M.createModel(window.RAIN_DATA);renderHistory()});});
